function modeUpload(mode){const label=mode==='proposal'?'上传你的开题报告':'上传你的论文';return `<label class="ppt-mode-drop ${deck.material?'has-material':''}" id="ppt-drop">${icon('upload',34)}<b>${busy?'正在解析…':'点击或拖拽文件上传'}</b><span>TXT / DOCX 最大 50MB；PDF 最大 20MB / 100 页</span><small>TXT / DOCX 本地提取；PDF（含扫描件）登录确认后云解析</small><input type="file" id="ppt-file" accept=".docx,.pdf,.txt" aria-label="${label}" ${busy?'disabled':''}></label><p id="ppt-material-state" class="ppt-mode-file-state ${deck.material?'has-material':'is-empty'}" aria-live="polite">${deck.material?`${esc(deck.fileName||'已上传文件')} · ${deck.material.length.toLocaleString('zh-CN')} 字符`:'尚未选择文件'}</p>`;}
function drawService(){const c=modeCopy[serviceMode];const ai=serviceMode==='ai';const label=serviceMode==='proposal'?'上传你的开题报告':'上传你的论文';const plan=serviceMode==='thesis'?`<div class="ppt-plan-row"><button class="ppt-plan ${pptTier==='basic'?'active':''}" data-ppt-tier="basic" aria-pressed="${pptTier==='basic'}"><b>▣ 答辩演示</b><strong>逐页内容与简洁备注</strong><span>真实材料整理、内容核对与 PPTX 导出</span></button><button class="ppt-plan ${pptTier==='premium'?'active':''}" data-ppt-tier="premium" aria-pressed="${pptTier==='premium'}"><b>▣ 演讲稿增强</b><strong>附逐页详细演讲备注</strong><span>围绕真实论文编排演示与讲述内容</span></button></div>`:'';root.innerHTML=`${toolBanner('ppt',{extraClass:'detail-service-banner',description:'从研究材料到清晰汇报，选择场景后逐页制作演示文稿。',actions:`<a class="btn secondary" href="#assets?scope=local">我的演示文稿</a>`})}<div class="ppt-mode-layout ppt-grid ppt-commercial doc-tool-detail doc-tool-ppt" data-presentation-mode="${serviceMode}">${modeNav()}<div class="ppt-mode-main">${pptJourney()}<div class="ppt-mode-banner">${icon('speaker',16)}${c.banner}</div>${plan}<section class="ppt-mode-card">${ai?`<div class="ppt-compose-heading"><span class="ppt-compose-number">01</span><div><h2>描述你的演示需求</h2><p>说明主题、听众与重点，AI 编排内容后由你逐页核对。</p></div><span class="ppt-compose-tag">AI 内容创作</span></div><div class="ppt-ai-input"><label class="ppt-ai-field-label" for="ppt-brief">主题与制作要求</label><textarea id="ppt-brief" data-field="prompt" maxlength="2800" aria-label="PPT 需求" placeholder="请输入你的指令要求，说明汇报用途、听众、时长与重点内容">${esc(deck.prompt||'')}</textarea><div class="ppt-ai-tools"><button type="button" data-action="pick-file">${icon('file',14)}上传参考文档</button><span class="ppt-tool-meta">${icon('pen',14)}AI 演讲备注</span><span class="ppt-tool-meta">材料驱动 · 内容可编辑</span><span class="ppt-tool-meta">16:9 · 可编辑 PPTX</span></div><input class="ppt-inline-file" type="file" id="ppt-file" accept=".docx,.pdf,.txt" aria-label="上传参考文档"><p id="ppt-material-state" class="ppt-mode-file-state ${deck.material?'has-material':'is-empty'}" aria-live="polite">${deck.material?`${esc(deck.fileName||'已上传参考文档')} · ${deck.material.length.toLocaleString('zh-CN')} 字符`:'尚未上传参考文档'}</p></div><details class="ppt-more ppt-material-review"><summary>填写或核对参考材料</summary><label>参考材料正文<textarea data-field="material" aria-label="材料正文" maxlength="80000" rows="7">${esc(deck.material)}</textarea></label><p>AI 每次最多读取 40,000 字符，不会静默截断；资料中的研究结果仍需核对。</p><button type="button" class="btn secondary" data-action="choose">从已有成果复制正文</button></details>${pptStartSettings()}<div class="ppt-quick-presets"><span>快捷指令</span>${quickLabels.map((x,i)=>`<button data-ppt-quick="${i}">${x}</button>`).join('')}</div><h3 class="ppt-section-title"><span class="ppt-compose-number">02</span> 选择演示版式</h3><div class="ppt-filter-groups"><p>选择一种风格作为起点。以下为本地编辑器封面示意，AI 根据内容编排生成文件；实际排版请下载核对。</p></div>${modeTemplates('ai')}<div class="ppt-mode-actions"><span class="ppt-action-note">${icon('shield',15)} 点击生成后自动处理，原稿与旧版本保留。</span><button class="btn primary" data-action="ai-generate">AI 生成演示文稿</button><button class="btn secondary" data-action="generate">免费创建结构</button><button class="btn secondary" data-action="custom-outline">自定义大纲</button></div>`:`<div class="ppt-compose-heading"><span class="ppt-compose-number">01</span><div><h2 class="ppt-mode-title">${label}</h2><p>${serviceMode==='proposal'?'从真实开题材料整理背景、研究目标与方法。':'从真实论文材料整理答辩结构与研究证据。'}</p></div><span class="ppt-compose-tag">导入真实材料</span></div>${modeUpload(serviceMode)}<details class="ppt-more"><summary>粘贴或核对材料正文</summary><label>材料正文<textarea data-field="material" aria-label="材料正文" maxlength="80000" rows="8">${esc(deck.material)}</textarea></label></details><label class="ppt-label ppt-parity-requirements">制作要求（可选）<textarea data-field="prompt" aria-label="PPT 需求" maxlength="2800" rows="3" placeholder="说明听众、汇报重点与材料范围">${esc(deck.prompt||'')}</textarea></label>${pptStartSettings()}<div class="ppt-template-label"><span class="ppt-compose-number">02</span>选择演示版式</div>${modeTemplates(serviceMode)}<div class="ppt-mode-actions"><span class="ppt-action-note">${icon('shield',15)} 点击生成后自动处理，原稿与旧版本保留。</span><button class="btn primary" data-action="ai-generate">AI 生成演示文稿</button><button class="btn secondary" data-action="generate">免费创建结构</button></div>`}</section></div></div>`;bindDrop();}
function slidePreview(slide,small=false,themeId=deck.theme){const t=themes[themeId]||themes.academic;return `<div class="ppt-slide ${slide.layout==='cover'?'cover':''} layout-${esc(slide.layout||'content')} ${small?'mini':''}" style="--ppt-accent:#${t.accent};--ppt-dark:#${t.dark}"><span>PaperKnow · ${esc(deck.scenario)}</span><h3>${esc(slide.title)}</h3><p>${esc(slide.body)}</p>${slide.layout==='cover'&&deck.author?'<span class="ppt-cover-author">作者：'+esc(deck.author)+'</span>':''}<small>${small?'':'16:9 · 文本预览'}</small></div>`;}
function drawEditor(){const slides=deck.slides,show=slides.length?slides[Math.min(preview,slides.length-1)]:{title:'论文题目示例',body:'毕业论文答辩\n作者 / 院校 / 导师',layout:'cover'};root.innerHTML=`${toolBanner('ppt',{extraClass:'detail-service-banner',description:'从论文到汇报，让研究表达更清晰。',actions:`<a class="btn secondary" href="#assets?scope=local">${icon('folder',16)} 我的演示文稿</a>`})}${generatedPresentation()}<div class="ppt-grid ppt-commercial ppt-editor-workspace doc-tool-detail doc-tool-ppt" data-presentation-mode="${serviceMode}"><section class="card ppt-card ppt-input-card doc-detail-panel"><header class="doc-detail-panel-head"><div><span class="doc-detail-eyebrow">01 · MATERIALS & STRUCTURE</span><h2>创作设置 <span class="hub-badge">AI 与逐页编辑</span></h2><p>整理材料与汇报要求，逐页编辑你的研究内容。</p></div></header><div class="ppt-tabs" data-scroll-key="ppt-tabs-1" role="group" aria-label="汇报场景">${scenarios.map(s=>`<button data-scenario="${s}" aria-pressed="${deck.scenario===s}" class="${deck.scenario===s?'active':''}">${s}</button>`).join('')}</div><ol class="ppt-steps">${['导入材料','确认大纲','编辑演示','导出文件'].map((s,i)=>`<li class="${i===(slides.length?2:0)?'active':''}"><span>${i+1}</span>${s}</li>`).join('')}</ol><b class="ppt-label">选择论文来源</b><div class="ppt-source-tabs">${[['upload','upload','上传论文'],['existing','folder','选择已有成果'],['paste','file','粘贴 / 核对材料']].map(([id,ico,n])=>`<button data-source="${id}" aria-pressed="${id===tab}" class="${id===tab?'active':''}">${icon(ico,16)}${n}</button>`).join('')}</div>${tab==='upload'?`<label class="ppt-drop" id="ppt-drop">${icon('upload',38)}<b>${busy?'正在解析…':'上传论文或报告'}</b><span>TXT / DOCX 最大 50MB；PDF 最大 20MB / 100 页</span><small>PDF 含扫描件，需登录并确认上传云端解析。</small><input type="file" id="ppt-file" accept=".docx,.pdf,.txt" aria-label="上传论文或报告" ${busy?'disabled':''}></label>`:tab==='paste'?`<label class="ppt-label">材料正文<textarea data-field="material" aria-label="材料正文" maxlength="80000" rows="7" placeholder="粘贴需要整理的研究材料；不会自动上传。">${esc(deck.material)}</textarea></label>`:'<div class="ppt-drop"><b>从论文成果开始</b><button class="btn secondary" data-action="choose">选择已有成果</button><small>复制正文，原成果不变。</small></div>'}<p id="ppt-material-state" class="hub-footnote">${deck.material?`${esc(deck.fileName||'粘贴材料')} · ${deck.material.length.toLocaleString('zh-CN')} 字符`:'尚未导入材料'}</p><div class="ppt-fields"><label>所属项目<select data-field="projectId" aria-label="所属项目" data-project-picker data-project-ref="${esc(deck.projectId||'')}">${projectPickerOptions(deck.projectId||'')}</select></label>${field('title','演示标题',deck.title,120)}</div><div class="ppt-fields four"><label>学段<select data-field="degree" aria-label="学段">${selectOptions(['专科','本科','硕士','博士','科研人员'],deck.degree)}</select></label><label>汇报时长（分钟）<input type="number" data-field="minutes" aria-label="汇报时长" min="1" max="120" value="${deck.minutes}"></label><label>目标页数<input type="number" data-field="pages" aria-label="目标页数" min="6" max="30" value="${deck.pages}"></label><label>演示语言<select data-field="language" aria-label="演示语言">${selectOptions(['中文','英文'],deck.language)}</select></label></div><label class="ppt-label">制作要求（可选）<textarea data-field="prompt" aria-label="PPT 需求" maxlength="2800" rows="3" placeholder="补充听众、表达重点或演讲备注要求">${esc(deck.prompt||'')}</textarea></label><details class="ppt-more"><summary>更多设置（作者、学校、导师）</summary><div class="ppt-fields">${field('author','作者',deck.author)}${field('school','学校 / 单位',deck.school)}${field('advisor','导师',deck.advisor)}</div></details>${notesSettings()}${outlineStatus()}<div class="ppt-actions"><button class="btn secondary" data-action="save">保存草稿</button><button class="btn primary" data-action="generate" ${busy?'disabled':''}>${slides.length?'重新创建大纲':'创建演示大纲'} ${icon('arrow',16)}</button></div><button class="btn primary" data-action="ai-generate">AI 重新创作</button><p class="hub-footnote">核对材料后可直接生成；采纳会保留当前页面备份。研究数据、结论与引用需依据实际材料核对。</p><p id="ppt-status" role="status" class="hub-footnote">${presentationScoped?'编辑暂存本页，请点击上方“保存到账户”。':dirty?'正在自动保存…':'已保存到当前浏览器，请及时导出备份。'}</p></section><aside class="ppt-preview-column"><section class="card ppt-card ppt-preview-card doc-detail-panel"><header class="doc-detail-panel-head"><div><span class="doc-detail-eyebrow">02 · PREVIEW & REVIEW</span><h2>当前内容预览 <span class="hub-badge gray">${slides.length?'当前文稿':'模板示例'}</span></h2><p>预览当前编辑内容的基础版式。生成版 PPTX 的实际排版请下载核对。</p></div></header><div class="ppt-tabs" data-scroll-key="ppt-tabs-2" role="group" aria-label="演示模板">${Object.entries(themes).map(([id,t])=>`<button data-theme="${id}" aria-pressed="${deck.theme===id}" class="${deck.theme===id?'active':''}">${t.name}</button>`).join('')}</div><div id="ppt-live-preview">${slidePreview(show)}</div><div class="ppt-thumbnails">${(slides.length?slides.slice(0,3):[{title:'论文题目示例',body:'答辩封面',layout:'cover'},{title:'研究方法',body:'填写实际研究设计'},{title:'结果分析',body:'填写真实研究证据'}]).map((s,i)=>`<button data-preview="${i}" aria-pressed="${preview===i}" aria-label="预览第 ${i+1} 页">${slidePreview(s,true)}</button>`).join('')}</div><p class="hub-footnote">16:9 · 文本可编辑 · 预览不保证与 PowerPoint 字体换行完全一致。</p></section><section class="card ppt-card"><h2>${slides.length?'演示大纲':'大纲结构预览'}</h2><div class="ppt-outline" data-scroll-key="ppt-outline-1">${(slides.length?slides:[{title:'研究背景与问题'},{title:'文献回顾'},{title:'研究设计与方法'},{title:'研究结果与分析'},{title:'结论与研究贡献'},{title:'致谢与答辩'}]).map((s,i)=>`<button data-edit="${i}" ${slides.length?'aria-current="'+(selected===i?'page':'false')+'"':'disabled'}><span>${String(i+1).padStart(2,'0')}</span>${esc(s.title)}${slides.length?icon('pen',14):''}</button>`).join('')}</div><p class="hub-footnote">${slides.length?'点击页面继续编辑；空缺内容不会被自动补造。':'示例结构，创建后可调整。'}</p></section></aside></div>${slides.length?editor():''}<section class="card ppt-card"><div class="hub-card-heading"><h2>最近演示文稿</h2><a href="#assets?scope=local">查看全部 →</a></div><div class="ppt-recents">${list(keys.drafts).filter(d=>d.tool==='ppt').sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,3).map(d=>`<a href="#draft/${esc(d.id)}">${icon('chart',24)}<div><b>${esc(d.title)}</b><p>${d.presentation?.slides?.length||0} 页 · ${formatDate(d.updatedAt)}${d.presentation?'':' · 旧版提纲'}</p><span>继续编辑 →</span></div></a>`).join('')||'<p class="hub-footnote">尚无保存的演示文稿，导入材料后开始创建。</p>'}</div></section><div class="ppt-backup">${icon('shield',20)}<div><b>文档解析与编辑，提交范围先确认</b><p>TXT / DOCX 本地提取，PDF 需登录确认后云解析。可导出文本、可编辑 PPTX 和打印预览；AI 创作按可用套餐或积分处理。</p></div></div>`;bindDrop();}
function draw(){jobPanel?.dispose();jobPanel=null;return withStableView(root,()=>{deck.slides.length?drawEditor():drawService();mountAI();});}
function mountAI(){const epoch=presentationEpoch;const box=document.createElement('section');box.className='card ppt-card ppt-ai-job';box.hidden=true;box.setAttribute('aria-label','AI 演示创作任务');root.append(box);if(presentationScoped){box.hidden=false;box.innerHTML='<h3>账户演示草稿</h3><p class="hub-footnote">本页支持逐页编辑与导出，编辑暂存在内存中，请使用上方“保存到账户”。AI 创作需要可恢复的任务标识，请在独立功能页生成后，再主动保存到账户。</p><a class="btn secondary" href="#category/ppt">打开 PPT 创作</a>';root.querySelectorAll('[data-action="ai-generate"]').forEach(button=>{button.disabled=true;button.title='请在独立 PPT 创作页生成后保存到账户';});return;}jobPanel=mountToolJobPanel({container:box,ctx,kind:'presentation',operation:'ppt',getSnapshot:()=>presentationSnapshot(deck,serviceMode,pptTier),getProjectRef:()=>deck.projectId||'',initialState:deck.aiJob||{},isCurrent:()=>epoch===presentationEpoch&&!!root?.isConnected,onStateChange:state=>{deck.aiJob=state;mark();if(!save(true))throw Error('AI 任务标识未能保存，请释放浏览器存储空间后重试；尚未提交新的付费任务。');},onApply:(output,item)=>{if(item?.id)deck.aiJob={...deck.aiJob,appliedJobId:item.id};const previous=structuredClone(deck);const slides=adoptPresentationOutput(output,deck);if(deck.slides.length)deck.versions=[{savedAt:new Date().toISOString(),slides:structuredClone(deck.slides)},...(deck.versions||[])].slice(0,5);deck.slides=slides;deck.sourceIds=output.sourceIds||[];const artifact=presentationArtifact(output);if(artifact)deck.generatedPresentation={...artifact,ownerId:deck.aiJob?.ownerId||'',jobId:item?.id||'',generatedAt:new Date().toISOString()};else delete deck.generatedPresentation;selected=0;preview=0;mark();if(!save(true)){deck=previous;throw Error('生成内容暂未保存，请释放浏览器空间后再次采纳。');}draw();ctx.notify(artifact?'生成版 PPTX 已保存到账户。逐页编辑的内容可另行导出为基础版式。':'已采纳 AI 演示内容，可逐页核对并导出 PPTX。');}});renderPresentationRecovery();}
function editor(){const s=deck.slides[selected]||deck.slides[0];selected=deck.slides.indexOf(s);return `<section class="card ppt-card doc-tool-detail doc-tool-ppt ppt-page-editor" data-presentation-mode="${serviceMode}" id="ppt-editor"><div class="hub-card-heading"><h2>逐页编辑 <span class="hub-badge">第 ${selected+1} / ${deck.slides.length} 页</span></h2><div class="ppt-actions"><button class="btn secondary" data-action="add">添加页</button><button class="btn secondary" data-action="up" ${selected===0?'disabled':''}>上移</button><button class="btn secondary" data-action="down" ${selected===deck.slides.length-1?'disabled':''}>下移</button><button class="btn secondary" data-action="remove" ${deck.slides.length===1?'disabled':''}>移除页</button></div></div><div class="ppt-editor-grid"><div class="ppt-page-fields"><label class="ppt-label">页面版式<select data-slide="layout" aria-label="页面版式">${[['cover','封面'],['content','内容'],['twoColumn','双栏内容'],['closing','结束页']].map(([value,label])=>`<option value="${value}" ${s.layout===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="ppt-label">页面标题<input data-slide="title" aria-label="页面标题" maxlength="120" value="${esc(s.title)}"></label><label class="ppt-label">页面正文<textarea data-slide="body" aria-label="页面正文" maxlength="1400" rows="6">${esc(s.body)}</textarea></label><label class="ppt-label">演讲备注<textarea data-slide="notes" aria-label="演讲备注" maxlength="3000" rows="3">${esc(s.notes)}</textarea></label></div><div class="ppt-source-reference"><details open><summary>参考材料（仅供核对）</summary><textarea readonly aria-label="参考材料" rows="10">${esc(deck.material)}</textarea></details><p class="hub-footnote">选取实际材料复制到左侧正文；每页建议保留 3–5 个要点。长文本在 PPTX 中可能缩小字号，请导出后核对。</p></div></div><div class="ppt-actions"><button class="btn primary" data-action="export">${deck.generatedPresentation?'导出当前内容（基础版式）':'导出可编辑 PPTX'}</button><button class="btn secondary" data-action="print">打印预览 / 保存 PDF</button><button class="btn secondary" data-action="text">导出文本</button><button class="btn secondary" data-action="json">导出文稿备份</button><button class="btn secondary" data-action="save">保存文稿</button>${deck.versions?.length?'<button class="btn secondary" data-action="restore-version">恢复上次页面</button>':''}</div></section>`;}
function mark(){dirty=true;clearTimeout(autosaveTimer);autosaveTimer=setTimeout(()=>save(true),450);const status=$('#ppt-status');if(status)status.textContent=presentationScoped?'编辑暂存本页，请点击上方“保存到账户”。':'正在自动保存…';}
function inputChange(e){if(e.target.dataset.pptFilter){deck.templateFilters={...(deck.templateFilters||{}),[e.target.dataset.pptFilter]:e.target.value};mark();draw();return;}if(e.target.dataset.field){deck[e.target.dataset.field]=['pages','minutes'].includes(e.target.dataset.field)?Number(e.target.value):e.target.value;if(e.target.dataset.field==='notesMode')pptTier=deck.notesMode==='detailed'?'premium':'basic';mark();if(e.target.dataset.field==='material')$('#ppt-material-state').textContent=`${deck.fileName||'粘贴材料'} · ${deck.material.length.toLocaleString('zh-CN')} 字符`;jobPanel?.inputChanged?.();}if(e.target.dataset.slide){deck.slides[selected][e.target.dataset.slide]=e.target.value;mark();preview=selected;if($('#ppt-live-preview'))$('#ppt-live-preview').innerHTML=slidePreview(deck.slides[selected]);const entry=$(`[data-edit="${selected}"]`);if(entry)entry.innerHTML=`<span>${String(selected+1).padStart(2,'0')}</span>${esc(deck.slides[selected].title)}${icon('pen',14)}`;}if(e.target.id==='ppt-file')readFile(e.target.files[0]);}
function freeze(value){root?.querySelectorAll('input,textarea,select,button').forEach(el=>{if(value){el.dataset.pptDisabled=String(el.disabled);el.disabled=true;}else if(el.dataset.pptDisabled!==undefined){el.disabled=el.dataset.pptDisabled==='true';delete el.dataset.pptDisabled;}});}
function bindDrop(){const grid=root.querySelector('.ppt-grid');if(grid&&!root.querySelector('.ppt-mode-layout')&&!root.querySelector('.ppt-service-panel'))grid.insertAdjacentHTML('beforebegin',pptServicePanel());const drop=$('#ppt-drop');if(!drop)return;drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag');});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files.length!==1)return ctx.notify('每次请选择一份文件。');readFile(e.dataTransfer.files[0]);});}
async function readFile(file){const epoch=presentationEpoch;if(!file||busy)return;if(!/\.(docx|pdf|txt)$/i.test(file.name)||file.size>50*1024*1024)return ctx.notify('TXT / DOCX 最大 50MB；PDF 最大 20MB / 100 页。');if(deck.material&&!confirm('替换当前参考材料？已编辑的页面会保留，请重新核对。'))return;busy=true;freeze(true);const mounted=root;const state=$('#ppt-material-state');if(state)state.textContent='正在准备文档解析…';try{if(epoch!==presentationEpoch)return;const r=await importWorkspaceDocument(file,state,{signal:controller.signal});if(epoch!==presentationEpoch)return;const text=validateMaterial(r.text);if(!mounted.isConnected)return;deck.material=text;deck.fileName=file.name;if(!deck.title)deck.title=file.name.replace(/\.[^.]+$/,'');mark();tab='paste';ctx.notify(r.warnings.length?'文件已解析，部分页面有解析提示，请核对正文。':'已解析正文，请核对。');}catch(e){if(epoch===presentationEpoch)ctx.notify(e.message||'文件解析失败。');}finally{if(epoch===presentationEpoch){busy=false;if(mounted.isConnected)draw();}}}
export function savePresentationDraft(){if(!root)return false;save();return !dirty;}
function save(quiet=false){if(!deck||!root||presentationScoped!==hasDraftScope())return false;if(!deck.title.trim()&&!quiet)return ctx.notify('请填写演示标题。');try{const rows=list(keys.drafts),old=rows.find(d=>d.id===deck.id),now=new Date().toISOString(),id=deck.id||crypto.randomUUID();const saved={...old,id,title:deck.title.trim()||deck.prompt?.trim().slice(0,40)||'未命名演示草稿',tool:'ppt',kind:deck.slides.length?'演示文稿':'演示草稿',stage:deck.slides.length?'presentation':'draft',projectId:deck.projectId,createdAt:old?.createdAt||now,updatedAt:now,text:deckText(deck),presentation:structuredClone({...deck,id,serviceMode,pptTier,autoSession:true})};write(keys.drafts,old?rows.map(d=>d.id===id?saved:d):[saved,...rows]);deck.id=id;dirty=false;if(!quiet)try{recordTask({id:'draft-'+id,title:deck.title,kind:'本地演示保存',status:'completed',projectId:deck.projectId,url:'#draft/'+id});}catch{}if(!quiet){ctx.notify(presentationScoped?'编辑已暂存本页，请点击上方“保存到账户”。':'文稿已保存到当前浏览器。');draw();}else{const status=$('#ppt-status');if(status)status.textContent=presentationScoped?'编辑已暂存本页，请点击上方“保存到账户”。':'已自动保存到当前浏览器。';}return true;}catch{if(!quiet)ctx.notify('浏览器保存失败，请导出文稿备份。');return false;}}
function choose(){const rows=list(keys.drafts).filter(d=>d.tool!=='ppt'&&(d.text?.trim()||d.html));ctx.modal('选择已有成果',`<p class="hub-footnote">复制已有正文；大纲与模板不代表真实论文。</p>${rows.map(d=>`<button class="ppt-existing" data-ppt-existing="${esc(d.id)}"><b>${esc(d.title)}</b><small>${esc(d.kind||'创作成果')}</small></button>`).join('')||'<p>暂无可导入成果。</p>'}`);document.querySelectorAll('[data-ppt-existing]').forEach(b=>b.addEventListener('click',()=>{const d=rows.find(d=>String(d.id)===b.dataset.pptExisting);if(deck.material&&!confirm('替换当前参考材料？'))return;let text=d.text||'';if(!text&&d.html){const div=document.createElement('div');div.innerHTML=d.html;div.querySelectorAll('p,h3,h4').forEach(n=>n.append(document.createTextNode('\n')));text=div.textContent||'';}try{deck.material=validateMaterial(text);deck.title=d.title;deck.projectId=d.projectId||deck.projectId;deck.fileName='已有成果：'+d.title;tab='paste';mark();document.querySelector('#workspace-dialog').close();draw();}catch(e){ctx.notify(e.message);}}));}
async function actions(e){const epoch=presentationEpoch;const b=e.target.closest('button');if(!b)return;if(busy)return ctx.notify('正在处理，请稍候。');if(b.dataset.pptMode){switchPresentationMode(b.dataset.pptMode);return;}if(b.dataset.pptTier){pptTier=b.dataset.pptTier;deck.notesMode=pptTier==='premium'?'detailed':'concise';mark();draw();return;}if(b.dataset.pptTemplatePreview){openTemplatePreview(b.dataset.pptTemplatePreview);return;}if(b.dataset.pptTemplate){deck.theme=Object.keys(themes)[Number(b.dataset.pptTemplate.split('-').pop())]||'academic';mark();draw();return;}if(b.dataset.pptQuick!==undefined){const labels=quickLabels;const label=labels[Number(b.dataset.pptQuick)];const nextMode=label==='开题报告'?'proposal':label==='论文答辩'?'thesis':serviceMode;if(nextMode!==serviceMode&&!switchPresentationMode(nextMode))return;if(!deck.title&&label)deck.title=label;if(serviceMode==='ai'&&!deck.prompt&&label)deck.prompt=`制作一份${label}演示文稿，按背景、核心内容、重点发现与总结组织结构。`;if(serviceMode!=='ai')deck.title=deck.title||modeCopy[serviceMode].title;mark();draw();return;}if(b.dataset.scenario){deck.scenario=b.dataset.scenario;mark();draw();return;}if(b.dataset.theme){deck.theme=b.dataset.theme;mark();draw();return;}if(b.dataset.source){tab=b.dataset.source;draw();if(tab==='existing')choose();return;}if(b.dataset.preview!==undefined){preview=Number(b.dataset.preview);draw();return;}if(b.dataset.edit!==undefined){selected=Number(b.dataset.edit);preview=selected;draw();return;}try{switch(b.dataset.action){case 'download-generated':await downloadGeneratedPresentation(epoch,b.dataset.fileRole||'deck');break;case 'ai-status':await jobPanel?.open();break;case 'ai-generate':if(presentationScoped)throw Error('账户草稿仅在内存编辑，请在独立 PPT 创作页生成后保存到账户。');await jobPanel.generate();break;case 'pick-file':$('#ppt-file')?.click();break;case 'choose':choose();break;case 'custom-outline':customOutlineDialog();break;case 'generate':if(!deck.title.trim())deck.title=serviceMode==='proposal'?'开题报告':serviceMode==='thesis'?'毕业论文答辩':'AI PPT';if(deck.slides.length&&!confirm('重新创建大纲将替换当前全部页面，请先保存或导出备份。确定继续？'))return;deck.slides=buildSlides({...deck,material:deck.material||deck.prompt||''});selected=0;preview=0;mark();draw();ctx.notify('已创建结构大纲，请逐页补充真实材料。');break;case 'restore-version':if(!deck.versions?.length)break;if(!confirm('恢复上次页面？当前页面会保留在备份中。'))break;{const previous=deck.versions.shift(),current=structuredClone(deck.slides);deck.slides=previous.slides;deck.versions.push({savedAt:new Date().toISOString(),slides:current});selected=0;preview=0;mark();draw();}break;case 'save':save();break;case 'add':if(deck.slides.length>=30)throw new Error('最多 30 页。');deck.slides.splice(selected+1,0,{id:crypto.randomUUID(),title:'新页面',body:'',notes:'',layout:'content'});selected++;preview=selected;mark();draw();break;case 'remove':if(!confirm('移除当前页并自动保存？删除前会保留一份页面备份，可恢复最近 5 次替换或删页。'))return;deck.versions=[{savedAt:new Date().toISOString(),label:'删除页面前',slides:structuredClone(deck.slides)},...(deck.versions||[])].slice(0,5);deck.slides.splice(selected,1);selected=Math.max(0,selected-1);preview=selected;mark();draw();break;case 'up':case 'down':{const next=selected+(b.dataset.action==='up'?-1:1);if(next<0||next>=deck.slides.length)return;[deck.slides[selected],deck.slides[next]]=[deck.slides[next],deck.slides[selected]];selected=next;preview=selected;mark();draw();break;}case 'export':busy=true;freeze(true);try{const exportScope=captureDraftScope(),snapshot=structuredClone(deck),current=()=>epoch===presentationEpoch&&exportScope.isCurrent()&&root?.isConnected;const {exportPresentation}=await import('./assets/presentation-export.js');if(!current())return;const bytes=await exportPresentation(snapshot);if(!current())return;await download((snapshot.title||'演示文稿')+'.pptx',bytes,'application/vnd.openxmlformats-officedocument.presentationml.presentation',{expectedUserId:exportScope.ownerId});if(!current())return;ctx.notify(deck.generatedPresentation?'已导出当前编辑内容的基础版式 PPTX，生成版文件仍单独保留。':'已导出 PPTX，请在 PowerPoint 中核对排版。');}finally{if(epoch===presentationEpoch){busy=false;freeze(false);}}break;case 'text':await download(deck.title+'.txt',deckText(deck));break;case 'json':await download((deck.title||'演示草稿')+'-PaperKnow.json',JSON.stringify(deck,null,2),'application/json');break;case 'print':validateDeck(deck);await download(deck.title+'-打印预览.html',printHtml(),'text/html');ctx.notify('已下载打印预览，打开后选择打印并保存 PDF。');break;}}catch(error){if(epoch===presentationEpoch)ctx.notify(error.message||'操作失败，请重试。');}}
function printHtml(){return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>${esc(deck.title)}</title><style>body{font-family:Arial,'Microsoft YaHei',sans-serif;margin:0;background:#eee}button{margin:20px;padding:12px}section{box-sizing:border-box;background:#fff;width:297mm;min-height:167mm;padding:22mm;page-break-after:always;border-left:4mm solid #${themes[deck.theme].accent}}h1{font-size:30pt;color:#${themes[deck.theme].dark}}p{font-size:20pt;white-space:pre-wrap;overflow-wrap:anywhere}.print-note{font-size:14px;margin:20px;line-height:1.8}@page{size:297mm 167mm;margin:0}@media print{button,.print-note{display:none}body{background:white}}</style><button onclick="window.print()">打印 / 保存 PDF</button><p class="print-note">这是当前编辑内容的基础打印预览。长正文会继续分页，打印页数可能多于演示页数；请在打印对话框核对分页。</p>${deck.slides.map(s=>`<section><small>PaperKnow · ${esc(deck.scenario)}</small><h1>${esc(s.title)}</h1>${s.layout==='cover'&&deck.author?'<small>作者：'+esc(deck.author)+'</small>':''}<p>${esc(s.body)}</p></section>`).join('')}</html>`;}
